#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    string s;
    cin >> s;
    vector<vector<long long>> ops(q, vector<long long>(3));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> ops[i][j];
        }
    }

    long long size = 1;
    while (size < n) size *= 2;
    vector<long long> ts(2 * size, 0), tm(2 * size, 0);
    for (long long i = 0; i < n; i++) {
        long long v = (s[i] == '(') ? 1 : -1;
        ts[size + i] = v;
        tm[size + i] = min(0LL, v);
    }
    for (long long v = size - 1; v >= 1; v--) {
        ts[v] = ts[2 * v] + ts[2 * v + 1];
        tm[v] = min(tm[2 * v], ts[2 * v] + tm[2 * v + 1]);
    }
    string out;
    for (long long k = 0; k < q; k++) {
        long long kind = ops[k][0], x = ops[k][1], y = ops[k][2];
        if (kind == 1) {
            long long v = size + x - 1;
            ts[v] = -ts[v];
            tm[v] = min(0LL, ts[v]);
            for (v /= 2; v >= 1; v /= 2) {
                ts[v] = ts[2 * v] + ts[2 * v + 1];
                tm[v] = min(tm[2 * v], ts[2 * v] + tm[2 * v + 1]);
            }
        } else {
            long long lo = size + x - 1, hi = size + y, ls = 0, lm = 0, rs = 0, rm = 0;
            while (lo < hi) {
                if (lo & 1) {
                    lm = min(lm, ls + tm[lo]);
                    ls += ts[lo];
                    lo++;
                }
                if (hi & 1) {
                    --hi;
                    rm = min(tm[hi], ts[hi] + rm);
                    rs = ts[hi] + rs;
                }
                lo /= 2;
                hi /= 2;
            }
            long long total = ls + rs, low = min(lm, ls + rm);
            if (!out.empty()) out += " ";
            out += (total == 0 && low >= 0) ? "YES" : "NO";
        }
    }
    cout << out << "\n";

    return 0;
}

