import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        String s = next();
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int size = 1;
        while (size < n) size *= 2;
        long[] ts = new long[2 * size];
        long[] tm = new long[2 * size];
        for (int i = 0; i < n; i++) {
            long v = (s.charAt(i) == '(') ? 1 : -1;
            ts[size + i] = v;
            tm[size + i] = Math.min(0, v);
        }
        for (int v = size - 1; v >= 1; v--) {
            ts[v] = ts[2 * v] + ts[2 * v + 1];
            tm[v] = Math.min(tm[2 * v], ts[2 * v] + tm[2 * v + 1]);
        }
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int x = (int) ops[k][1], y = (int) ops[k][2];
            if (kind == 1) {
                int v = size + x - 1;
                ts[v] = -ts[v];
                tm[v] = Math.min(0, ts[v]);
                for (v /= 2; v >= 1; v /= 2) {
                    ts[v] = ts[2 * v] + ts[2 * v + 1];
                    tm[v] = Math.min(tm[2 * v], ts[2 * v] + tm[2 * v + 1]);
                }
            } else {
                int lo = size + x - 1, hi = size + y;
                long ls = 0, lm = 0, rs = 0, rm = 0;
                while (lo < hi) {
                    if ((lo & 1) == 1) {
                        lm = Math.min(lm, ls + tm[lo]);
                        ls += ts[lo];
                        lo++;
                    }
                    if ((hi & 1) == 1) {
                        --hi;
                        rm = Math.min(tm[hi], ts[hi] + rm);
                        rs = ts[hi] + rs;
                    }
                    lo /= 2;
                    hi /= 2;
                }
                long total = ls + rs, low = Math.min(lm, ls + rm);
                if (out.length() > 0) out.append(" ");
                out.append((total == 0 && low >= 0) ? "YES" : "NO");
            }
        }
        System.out.println(out);
    }
}
